import{_ as n,C as i,o as h,c as d,a5 as r,j as t,a,E as o}from"./chunks/framework.-jms6n7v.js";const y=JSON.parse('{"title":"File format","description":"This page summarises how a DaruDB database file is laid out: its pages, the header and its three commit slots, the pointers that verify every page, and how the…","frontmatter":{"title":"File format","order":3,"prev":{"text":"How the engine is built","link":"/engine/architecture"},"next":{"text":"Commits and recovery","link":"/engine/commits-and-recovery"}},"headers":[{"level":2,"title":"Pages","slug":"pages","link":"#pages","children":[]},{"level":2,"title":"The header","slug":"the-header","link":"#the-header","children":[{"level":3,"title":"The selector","slug":"the-selector","link":"#the-selector","children":[]},{"level":3,"title":"Three commit slots","slug":"three-commit-slots","link":"#three-commit-slots","children":[]}]},{"level":2,"title":"The page envelope","slug":"the-page-envelope","link":"#the-page-envelope","children":[]},{"level":2,"title":"Pointers and checks","slug":"pointers-and-checks","link":"#pointers-and-checks","children":[]},{"level":2,"title":"Trees","slug":"trees","link":"#trees","children":[{"level":3,"title":"Objects in trees","slug":"objects-in-trees","link":"#objects-in-trees","children":[]}]},{"level":2,"title":"Reading a file","slug":"reading-a-file","link":"#reading-a-file","children":[]},{"level":2,"title":"Format versions","slug":"format-versions","link":"#format-versions","children":[]}],"relativePath":"engine/file-format.md","filePath":"en/engine/file-format.md","lastUpdated":1791607937000}'),l={name:"engine/file-format.md"};function c(g,e,p,f,m,u){const s=i("LangCode");return h(),d("div",null,[e[10]||(e[10]=r('<h1 id="file-format" tabindex="-1">File format <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;File format&quot;">​</a></h1><p>This page summarises how a DaruDB database file is laid out: its pages, the header and its three commit slots, the pointers that verify every page, and how the format is versioned.</p><p>The specification, with every offset and field, is <a href="https://github.com/jooy2/darudb/blob/main/design/file-format.md" target="_blank" rel="noreferrer">design/file-format.md</a> in the repository. It describes format version 6, the one this build writes, and version 5, which it reads and writes too.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><p>A database is one file, divided into pages of equal size.</p><ul><li><strong>The page size</strong> is a power of two from 4096 to 65536 bytes, chosen when the file is created and recorded in its header. 4096 is the default. Larger pages made scans and counts faster in the benchmarks, but a lookup in a file larger than the page cache slower, since a miss reads and checks a whole page, and a small commit slower, since it writes whole pages. An application that mostly scans can choose more when it creates the file.</li><li><strong>Page numbers</strong> are 64-bit. Page 0 is the header, and every other page is a node of a B+tree or part of a large value.</li><li><strong>The operating system&#39;s memory page size</strong> plays no part. The engine never maps the file, so it never assumes one, which matters on Android, where memory pages are now 16 KB.</li><li><strong>Each commit counts the file&#39;s pages.</strong> Pages past that count are not part of the commit.</li><li><strong>The file never reaches byte 2^62</strong>, where the lock bytes begin (<a href="./locking">Locking</a>).</li></ul><h2 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h2><p>Page 0 is never encrypted, because it says how to read everything else, the key included. Its first 2048 bytes are laid out in sectors of 512 bytes, so that on a disk with 512-byte sectors a write to one commit slot cannot damage another.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>What they hold</th></tr></thead><tbody><tr><td>0 to 63</td><td>The static fields: the magic bytes <code>\\x89DaruDB\\n</code>, the format version, the page size, a file id of 16 random bytes, the cipher, and a check of them all. Written when the file is created, and again only to raise its format version.</td></tr><tr><td>64</td><td>The selector</td></tr><tr><td>128 to 191</td><td>The raised static fields: the new static fields, which raising the format version writes first</td></tr><tr><td>512 to 2047</td><td>Three commit slots of 512 bytes each</td></tr></tbody></table><p>The magic&#39;s first byte is outside ASCII, so the file is never mistaken for text and a transfer that strips the eighth bit is caught. Its last byte, a newline, catches a transfer that rewrites line endings.</p><h3 id="the-selector" tabindex="-1">The selector <a class="header-anchor" href="#the-selector" aria-label="Permalink to &quot;The selector&quot;">​</a></h3><p>One byte, rewritten on every commit. Two bits name the slot that holds the published commit, the one a new reader sees. One bit, the unsynced bit, is set when that commit was deferred and may not be durable yet. A one-byte write is atomic, so a reader, or a recovery after a power cut, sees either the old selector or the new one, and readers find the published commit without taking a lock.</p><h3 id="three-commit-slots" tabindex="-1">Three commit slots <a class="header-anchor" href="#three-commit-slots" aria-label="Permalink to &quot;Three commit slots&quot;">​</a></h3><p>Each slot holds one commit record or nothing. A record holds the commit&#39;s transaction id, the transaction id of the newest commit known to be durable when it was written, the page count, the roots of the engine&#39;s three trees described below, the key block and a MAC in an encrypted file, for a deferred commit when its unsynced window opened and how many pages the window has written, and a check that mixes in the slot number, so that a record written into the wrong slot fails it.</p><p>Three is the fewest that works. At any moment one slot holds the published commit and one holds the durable commit, which differ while deferred commits wait for the disk, and the writer needs a third place for the record it is writing. So a new record never overwrites one that a reader or a recovery may still need. <a href="./commits-and-recovery">Commits and recovery</a> says how the writer chooses.</p><h2 id="the-page-envelope" tabindex="-1">The page envelope <a class="header-anchor" href="#the-page-envelope" aria-label="Permalink to &quot;The page envelope&quot;">​</a></h2><p>Every page other than page 0 has the same frame:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>What they hold</th></tr></thead><tbody><tr><td>0 to 23</td><td>The nonce of an encrypted page, and zeros in a plain file</td></tr><tr><td>24 to 55</td><td>The page header: the kind (leaf, branch or overflow), the level, the entry count, the transaction id of the commit that wrote the page, the id of its tree, and an overflow page&#39;s position in its run</td></tr><tr><td>56 to the last 16</td><td>The content</td></tr><tr><td>The last 16</td><td>The page&#39;s check</td></tr></tbody></table><ul><li><strong>Every page reserves the nonce field</strong>, encrypted or not. A tree built by the same operations then has the same shape with and without encryption, which lets one test suite cover both. The cost is 24 bytes a page, 0.6% at 4096 bytes.</li><li><strong>The page header repeats what the parent knows</strong>, so that a page can be understood on its own. The integrity check compares it with what the parent expects, and salvage uses it to put pages back into trees whose parents are lost.</li></ul><h2 id="pointers-and-checks" tabindex="-1">Pointers and checks <a class="header-anchor" href="#pointers-and-checks" aria-label="Permalink to &quot;Pointers and checks&quot;">​</a></h2><p>Every reference from one page to another, and from the header to a tree&#39;s root, is a pointer of 32 bytes: the page number (8 bytes), the transaction id of the commit that wrote the page (8), and the page&#39;s check (16).</p><ul><li><strong>The check</strong> is the XXH3-128 hash of the page number and the page&#39;s bytes in a plain file, and the page&#39;s authentication tag in an encrypted one (<a href="./encryption">Encryption</a>). Mixing in the page number means a page written to the wrong place fails its own check.</li><li><strong>Every page is verified against the pointer that led to it</strong> before anything in it is used: its check has to match, and so does the transaction id in its header. That catches a page damaged on the disk, a stale page left behind by a write that never reached it, and a page written to the wrong place. A page that fails is reported as <code>CORRUPTED</code>, never read.</li><li><strong>The transaction id makes recovery cheap.</strong> After a crash, recovery checks only the pages written since the last durable commit, and the ids in the pointers tell it which children those are without reading the others.</li></ul><p>XXH3-128 is fast enough that checking every page on every read costs little, and 128 bits make an accidental match negligible across billions of pages. It is not a cryptographic hash and does not have to be: it catches accidents, and an encrypted file&#39;s tags are what stop deliberate changes.</p><h2 id="trees" tabindex="-1">Trees <a class="header-anchor" href="#trees" aria-label="Permalink to &quot;Trees&quot;">​</a></h2><p>Every tree has an id, which each of its pages carries, and a tree id is never reused, so salvage can tell which tree a page belonged to across the file&#39;s whole history.</p><table tabindex="0"><thead><tr><th>Id</th><th>Tree</th></tr></thead><tbody><tr><td>1</td><td>The catalog: each tree&#39;s name, with its id, its root and its entry count</td></tr><tr><td>2</td><td>The free tree: runs of pages nothing can reach any more, which the writer may use</td></tr><tr><td>3</td><td>The retained tree: pages that only an older commit still reaches, grouped by the commit that stopped using them, until no reader or recovery can need them</td></tr><tr><td>4 to 15</td><td>Reserved for the engine</td></tr><tr><td>16 and up</td><td>Trees of the layers above: the storage kernel&#39;s trees, and the collections and indexes of the object layer</td></tr></tbody></table><ul><li><strong>Leaves</strong> hold entries in key order, through an array of 2-byte offsets at the start of their content. <strong>Branches</strong> hold child pointers and the separator keys between them.</li><li><strong>An entry&#39;s lengths are varints</strong> in format 6: the key&#39;s length and a tag that gives the value&#39;s length or says the value is in an overflow run, each in one byte for a key shorter than 128 bytes and a value shorter than 64. Format 5 spent five bytes on them. An index&#39;s entries are short, so its leaves hold about a fifth more of them. A leaf&#39;s page kind says which layout it has, so a file raised from format 5 holds leaves of both.</li><li><strong>Leaves are not linked to their neighbours.</strong> In a copy-on-write tree, a link would mean rewriting the neighbour every time a leaf is copied, so a walk keeps its path from the root instead.</li><li><strong>A large value</strong> goes into an overflow run of consecutive pages, and its entry holds a reference of 44 bytes with a check over the checks of the run&#39;s pages.</li><li><strong>Keys order as unsigned bytes</strong>, and nothing else. A key is at most a quarter of a page, less a few bytes, which guarantees that four entries always fit in a node, so a node that overflows can always be split.</li><li><strong>The catalog keeps each tree&#39;s entry count</strong>, so counting a whole tree costs nothing.</li></ul><h3 id="objects-in-trees" tabindex="-1">Objects in trees <a class="header-anchor" href="#objects-in-trees" aria-label="Permalink to &quot;Objects in trees&quot;">​</a></h3><p>The object layer stores everything in trees whose names begin with the byte <code>0x00</code>, which the catalog reserves for the engine. <code>\\0meta</code> holds the stored schema and the collections&#39; auto-increment counters, each collection&#39;s objects are in a tree from the encoded primary key to the object&#39;s record, and each index is a tree of its own. Keys are encoded so that their bytes sort as their values do, and records hold field ids rather than names, so renaming a field rewrites nothing. The stored schema carries a format number of its own for these encodings. <a href="https://github.com/jooy2/darudb/blob/main/design/objects.md" target="_blank" rel="noreferrer">design/objects.md</a> specifies them.</p><h2 id="reading-a-file" tabindex="-1">Reading a file <a class="header-anchor" href="#reading-a-file" aria-label="Permalink to &quot;Reading a file&quot;">​</a></h2><p>Anything read from the file is treated as untrusted input. Before it is used, the engine checks the magic, the format version, the static check, the page size and the cipher, the selector&#39;s reserved bits, each commit record it uses, and each page: that it lies inside the file and below the page count, that its check, transaction id, kind, level and tree are what its pointer and parent expect, and that every offset and length inside it stays inside it. A damaged file produces an error, <code>CORRUPTED</code> for damage and <code>NOT_A_DATABASE</code> for a file that is not a DaruDB database at all, and never brings the program down.</p><p>Checks that span several pages, such as whether every key under a branch lies between its separators, belong to the integrity check rather than to every read (<a href="./../guide/tools">Tools</a>).</p><h2 id="format-versions" tabindex="-1">Format versions <a class="header-anchor" href="#format-versions" aria-label="Permalink to &quot;Format versions&quot;">​</a></h2><p>The header&#39;s format version names the layout of everything on disk, and any change to what is written changes it.</p>',34)),t("ul",null,[e[3]||(e[3]=t("li",null,[t("strong",null,"This build writes format version 6, and reads and writes version 5 too."),a(" A file in any other version, older or newer, is refused with "),t("code",null,"UNSUPPORTED_FORMAT_VERSION"),a(", and the error names the version found. The first 16 bytes of the header have kept the same layout since version 1, so every build can at least tell a DaruDB file and its version apart.")],-1)),e[4]||(e[4]=t("li",null,[t("strong",null,"Version 5 is the format of the first release"),a(", version 1.0 of every package. Versions 1 to 4 never left development, so a file one of their builds wrote is refused, not upgraded.")],-1)),e[5]||(e[5]=t("li",null,[t("strong",null,"Version 6 writes the lengths in a leaf's entries as varints."),a(" A file of 400,000 objects with 14 indexes takes 8% fewer pages than in version 5, 126 MiB against 138 MiB, and compacts to 110 MiB against 119 MiB. Reads and writes measured as fast as in version 5, within the benchmarks' noise of about 2%.")],-1)),t("li",null,[e[0]||(e[0]=t("strong",null,"Every later format version comes with a migration from the one before.",-1)),e[1]||(e[1]=a(" Opening a file of version 5 raises it to version 6, while no other process has the file open, unless ",-1)),o(s,{rust:"OpenOptions::upgrade_format(false)",node:"upgradeFormat: false",dart:"upgradeFormat: false",python:"upgrade_format=False"}),e[2]||(e[2]=a(" turns that off.",-1))])]),t("p",null,[e[6]||(e[6]=a("Raising the version rewrites the header and nothing else. The leaves the file holds keep their layout, which version 6 reads, until a write changes them and writes them in the new one; compaction rewrites the trees where the new layout saves room. A release that knows only version 5 refuses the file once it is raised, so an application that may go back to one turns raising off, which also creates new files in version 5, and calls ",-1)),o(s,{rust:"Database::upgrade_format",node:"db.upgradeFormat()",dart:"db.upgradeFormat()",python:"db.upgrade_format()"}),e[7]||(e[7]=a(" once it no longer may. That call needs the file to itself, and fails with ",-1)),e[8]||(e[8]=t("code",null,"BUSY",-1)),e[9]||(e[9]=a(" while another process has it open.",-1))]),e[11]||(e[11]=r('<p>The static check covers the version, and only a one-byte write is atomic, so the raise writes the new static fields to bytes 128 to 191 first, then the version&#39;s byte, then the new check, with a barrier after each. A cut anywhere leaves a file that opens in one version or the other: once the version&#39;s byte is written, a check that does not match it is vouched for by the copy, and the next process to open the file alone writes it.</p><div class="lang-only" data-code-lang="rust"><p>The newest version a build writes is <code>darudb::FORMAT_VERSION</code> (<a href="./../types/rust/constants">constants</a>).</p></div><div class="lang-only" data-code-lang="node"><p>The newest version a build writes is <code>FORMAT_VERSION</code> (<a href="./../types/node/constants">constants</a>).</p></div><div class="lang-only" data-code-lang="dart"><p>The newest version a build writes is <code>formatVersion</code> (<a href="./../types/dart/constants">constants</a>).</p></div><div class="lang-only" data-code-lang="python"><p>The newest version a build writes is <code>darudb.FORMAT_VERSION</code> (<a href="./../types/python/constants">constants</a>).</p></div>',5))])}const w=n(l,[["render",c]]);export{y as __pageData,w as default};
